python3 << 'EOF'
# Let me search more comprehensively for any budget projection data
# that might span multiple years - perhaps I'm missing a table

import os
import re

for file in os.listdir('/app/resources'):
    if file.endswith('.txt'):
        filepath = os.path.join('/app/resources', file)
        try:
            with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()
                # Find any table that mentions years 2020+
                if re.search(r'202[0-9]', content):
                    # Find specific sections
                    if any(term in content.lower() for term in ['surplus', 'deficit', 'outlook', 'projection', 'forecast']):
                        print(f"\n{file}:")
                        # Find all year mentions
                        years = re.findall(r'\b202[0-9]\b', content)
                        print(f"  Years 2020+: {sorted(set(years))}")
                        # Show context
                        for m in re.finditer(r'202[0-9]', content):
                            start = max(0, m.start()-50)
                            end = min(len(content), m.end()+50)
                            context = content[start:end]
                            if any(term in context.lower() for term in ['surplus', 'deficit', 'estimate', 'budget']):
                                print(f"    Context: ...{context}...")
                                break
        except:
            pass
EOF
